//! The shared runtime every generated store builds on, as gormx is for gorm:
//! [`Query`], the window-and-tag query a store's `query()` starts, the
//! [`Column`] its tag and field enums implement, and strict record decoding.

use database::store::{
    AggregateOptions, Bucket, Error, For, ListOptions, Model, RangeOptions, Reducer, Reduction,
    Result,
};
use std::collections::BTreeSet;
use std::time::Duration;

/// A stored column a query names: a store's `Tag` or `Field` variant.
pub trait Column: Copy {
    /// The column's stored name.
    fn column(self) -> &'static str;
}

/// Reduces `column` with `func`, reported as `<func>_<column>` ("avg_temperature").
pub fn reduce(func: Reducer, column: impl Column) -> Reduction {
    let name = match func {
        Reducer::Count => "count",
        Reducer::Sum => "sum",
        Reducer::Avg => "avg",
        Reducer::Min => "min",
        Reducer::Max => "max",
    };
    Reduction::new(func, column.column(), format!("{name}_{}", column.column()))
}

/// One table's points, narrowed by a time window, tag equalities and any
/// AIP-160 conjunction, then read as a page, every point, the newest point, a
/// count, or reduced buckets. Built by a store's `query()`; the tag methods
/// (`.device_id("…")`) are generated beside each store.
#[derive(Clone)]
pub struct Query<T> {
    rows: For<T>,
    start: i64,
    end: i64,
    filters: Vec<String>,
    group_by: Vec<String>,
    descending: bool,
    page_size: i32,
    page_token: String,
    error: Option<String>,
}

impl<T: Model> Query<T> {
    /// Every point of the table, oldest first.
    pub fn new(rows: For<T>) -> Self {
        Self {
            rows,
            start: i64::MIN,
            end: i64::MAX,
            filters: Vec::new(),
            group_by: Vec::new(),
            descending: false,
            page_size: 0,
            page_token: String::new(),
            error: None,
        }
    }

    /// Points in the half-open window [start, end), epoch nanoseconds.
    pub fn between(mut self, start: i64, end: i64) -> Self {
        (self.start, self.end) = (start, end);
        self
    }

    /// Points at or after `start`.
    pub fn since(mut self, start: i64) -> Self {
        self.start = start;
        self
    }

    /// Points before `end`.
    pub fn until(mut self, end: i64) -> Self {
        self.end = end;
        self
    }

    /// Points whose `column` holds `value`.
    pub fn eq(mut self, column: impl Column, value: &str) -> Self {
        match literal(value) {
            Ok(v) => self.filters.push(format!("{} = {v}", column.column())),
            Err(e) => self.error = Some(e),
        }
        self
    }

    /// Points matching an AIP-160 conjunction, such as `"value > 30"`.
    pub fn filter(mut self, expr: impl Into<String>) -> Self {
        self.filters.push(expr.into());
        self
    }

    /// Newest points first.
    pub fn newest_first(mut self) -> Self {
        self.descending = true;
        self
    }

    /// Points per page; 0 for the runtime's default of 50.
    pub fn page_size(mut self, size: i32) -> Self {
        self.page_size = size;
        self
    }

    /// Continues from a previous page's token.
    pub fn page_token(mut self, token: impl Into<String>) -> Self {
        self.page_token = token.into();
        self
    }

    /// Also splits each aggregate bucket by `tag`.
    pub fn group_by(mut self, tag: impl Column) -> Self {
        self.group_by.push(tag.column().to_owned());
        self
    }

    fn checked(&self) -> Result<String> {
        match &self.error {
            Some(e) => Err(Error::Invalid(e.clone())),
            None => Ok(self.filters.join(" AND ")),
        }
    }

    fn range(&self) -> Result<RangeOptions> {
        Ok(RangeOptions {
            start: self.start,
            end: self.end,
            descending: self.descending,
            filter: self.checked()?,
            page_size: self.page_size,
            page_token: self.page_token.clone(),
            ..Default::default()
        })
    }

    /// One page and the token of the next, empty on the last.
    pub async fn fetch(self) -> Result<(Vec<T>, String)> {
        self.rows.range(&self.range()?).await
    }

    /// Every matching point, following page tokens. Costs memory for each.
    pub async fn all(self) -> Result<Vec<T>> {
        let mut opts = self.range()?;
        let (mut out, mut seen) = (Vec::new(), BTreeSet::new());
        loop {
            let (page, next) = self.rows.range(&opts).await?;
            out.extend(page);
            if next.is_empty() {
                return Ok(out);
            }
            if !seen.insert(next.clone()) {
                return Err(Error::Invalid(
                    "repeated page token; refusing to loop".into(),
                ));
            }
            opts.page_token = next;
        }
    }

    /// The newest matching point, if any.
    pub async fn latest(self) -> Result<Option<T>> {
        let (page, _) = self.newest_first().page_size(1).fetch().await?;
        Ok(page.into_iter().next())
    }

    /// How many points match.
    pub async fn count(self) -> Result<i64> {
        let mut clauses = vec![self.checked()?];
        let time = self.rows.resource().time_column()?;
        if self.start != i64::MIN {
            clauses.push(format!("{time} >= {}", self.start));
        }
        if self.end != i64::MAX {
            clauses.push(format!("{time} < {}", self.end));
        }
        clauses.retain(|c| !c.is_empty());
        let opts = ListOptions::default().filter(clauses.join(" AND "));
        self.rows.count(&opts).await
    }

    /// Buckets `every` wide over the window, each holding `reduce`'s values by
    /// alias (`<func>_<column>`). Reductions come from a store's `Field` enum:
    /// `Field::Temperature.avg()`.
    pub async fn aggregate(
        self,
        every: Duration,
        reduce: impl IntoIterator<Item = Reduction>,
    ) -> Result<Vec<Bucket>> {
        let opts = AggregateOptions {
            start: self.start,
            end: self.end,
            every,
            reduce: reduce.into_iter().collect(),
            group_by: self.group_by.clone(),
            filter: self.checked()?,
            ..Default::default()
        };
        self.rows
            .db()
            .series
            .aggregate(self.rows.resource(), &opts)
            .await
    }
}

/// A filter literal for `value`. The runtime's filters have no escapes, so
/// the quote is whichever the value does not contain.
fn literal(value: &str) -> std::result::Result<String, String> {
    if !value.contains('"') {
        Ok(format!("\"{value}\""))
    } else if !value.contains('\'') {
        Ok(format!("'{value}'"))
    } else {
        Err(format!(
            "filter value {value:?} holds both quote characters"
        ))
    }
}

/// Strict decoding of stored records: a missing column, or a value of the
/// wrong kind or out of the field's range, is an error rather than a default.
pub(crate) mod decode {
    use database::store::{Error, Record, Value};

    fn take(record: &mut Record, name: &str) -> database::Result<Value> {
        record
            .remove(name)
            .ok_or_else(|| Error::Invalid(format!("missing column {name}")))
    }

    fn wrong(name: &str, want: &str, got: &Value) -> Error {
        Error::Invalid(format!("column {name}: expected {want}, got {got}"))
    }

    #[allow(dead_code)]
    pub(crate) fn string(record: &mut Record, name: &str) -> database::Result<String> {
        match take(record, name)? {
            Value::String(s) => Ok(s),
            other => Err(wrong(name, "a string", &other)),
        }
    }

    pub(crate) fn int<T: TryFrom<i64>>(record: &mut Record, name: &str) -> database::Result<T> {
        let value = take(record, name)?;
        value
            .as_i64()
            .and_then(|n| T::try_from(n).ok())
            .ok_or_else(|| wrong(name, "an integer in range", &value))
    }

    #[allow(dead_code)]
    pub(crate) fn uint<T: TryFrom<u64>>(record: &mut Record, name: &str) -> database::Result<T> {
        let value = take(record, name)?;
        value
            .as_u64()
            .and_then(|n| T::try_from(n).ok())
            .ok_or_else(|| wrong(name, "an unsigned integer in range", &value))
    }

    #[allow(dead_code)]
    pub(crate) fn float(record: &mut Record, name: &str) -> database::Result<f64> {
        let value = take(record, name)?;
        value
            .as_f64()
            .ok_or_else(|| wrong(name, "a number", &value))
    }

    #[allow(dead_code)]
    pub(crate) fn boolean(record: &mut Record, name: &str) -> database::Result<bool> {
        let value = take(record, name)?;
        value
            .as_bool()
            .ok_or_else(|| wrong(name, "a boolean", &value))
    }
}
